// ---- Edit these to match your business ----
const ALLOWED_EMAIL_DOMAINS = ['example.com'];   // empty array = allow any domain
const MAX_DETAILS_CHARS = 2000;
const REPEAT_WINDOW_MS = 60 * 60 * 1000;
const REQUIRED = {
  log_note:    ['customer', 'details'],
  create_task: ['customer', 'details'],
  draft_email: ['customer', 'details'],
  notify_team: ['details']
};
// -------------------------------------------

const inp = $json;
const action = String(inp.action || '').trim();
const customer = String(inp.customer || '').trim();
const requestedBy = String(inp.requested_by || '').trim() || 'unattributed';
let details = String(inp.details || '').trim();
const problems = [];

if (!REQUIRED[action]) {
  problems.push('Unknown action "' + action + '". This server only accepts: ' + Object.keys(REQUIRED).join(', ') + '.');
} else {
  REQUIRED[action].forEach(function (f) {
    if (!String(inp[f] || '').trim()) problems.push('Missing required field: ' + f + '.');
  });
}

if (details.length > MAX_DETAILS_CHARS) details = details.slice(0, MAX_DETAILS_CHARS);

// Never let something that looks like a credential get written into your systems
let redactions = 0;
const secretPatterns = [/\b(sk|pk)-[A-Za-z0-9]{16,}\b/g, /\bBearer\s+[A-Za-z0-9._-]{16,}\b/g, /\b[A-Fa-f0-9]{32,}\b/g];
secretPatterns.forEach(function (re) {
  details = details.replace(re, function () { redactions++; return '[redacted]'; });
});

let recipient = '';
if (action === 'draft_email') {
  const m = details.match(/[\w.+-]+@[\w-]+\.[\w.-]+/);
  recipient = m ? m[0] : '';
  if (!recipient) {
    problems.push('draft_email needs a recipient address inside details.');
  } else {
    const domain = recipient.split('@')[1].toLowerCase();
    if (ALLOWED_EMAIL_DOMAINS.length && ALLOWED_EMAIL_DOMAINS.indexOf(domain) === -1) {
      problems.push('Refusing to draft to ' + domain + '. Add it to ALLOWED_EMAIL_DOMAINS if that is intended.');
    }
  }
}

let dueDate = '';
if (action === 'create_task') {
  const d = details.match(/\d{4}-\d{2}-\d{2}/);
  dueDate = d ? d[0] : '';
  if (dueDate && new Date(dueDate) < new Date(new Date().toDateString())) {
    problems.push('Due date ' + dueDate + ' is in the past.');
  }
}

// Stop the model repeating itself - a loop must not spam the team or the sheet
const state = $getWorkflowStaticData('global');
state.recent = (state.recent || []).filter(function (r) { return Date.now() - r.at < REPEAT_WINDOW_MS; });
const fingerprint = action + '|' + customer + '|' + details.slice(0, 120);
if (state.recent.some(function (r) { return r.fp === fingerprint; })) {
  problems.push('An identical ' + action + ' was already carried out within the last hour. Not repeating it.');
}

const allowed = problems.length === 0;
if (allowed) state.recent.push({ fp: fingerprint, at: Date.now() });

return [{ json: {
  allowed: allowed, action: action, customer: customer, requestedBy: requestedBy,
  details: details, recipient: recipient, dueDate: dueDate, redactions: redactions,
  reason: allowed ? 'Passed every policy check' : problems.join(' ')
} }];

const p = $('Check the Policy').first().json;

if (!p.allowed) {
  return [{ json: { result: 'BLOCKED. ' + p.reason + ' Nothing was changed, and the refusal is in the audit log. Tell the user plainly what was refused and why. Do not retry with the same arguments.' } }];
}

const done = {
  log_note: 'A note was logged against ' + p.customer + '.',
  create_task: 'A follow-up task was created for ' + p.customer + (p.dueDate ? ', due ' + p.dueDate : ', with no due date') + '.',
  draft_email: 'A Gmail DRAFT was created for ' + p.recipient + '. It has NOT been sent - a person must open it, review it and send it.',
  notify_team: 'The account team was notified in Slack.'
};

const extra = p.redactions ? ' ' + p.redactions + ' value(s) that looked like credentials were redacted before writing.' : '';
return [{ json: { result: (done[p.action] || 'Done.') + extra + ' Recorded in the audit log.' } }];
